css_code = """@import url('https://fonts.googleapis.com/css2?family=Assistant:wght@400;500;600;700;800&family=Rubik:wght@400;500;600;700&family=Bellefair&family=David+Libre:wght@400;500;700&family=Frank+Ruhl+Libre:wght@400;700;900&family=Noto+Serif+Hebrew:wght@400;700;900&display=swap');

/* ============================================================
   משתני CSS גלובליים: רשת העמוד, טיפוגרפיה וצבעים
   ============================================================ */
:root {
    --preview-scale: 1;
    --fn-header-r: 'Livorna', 'David Libre', 'David', serif;
    --sz-header-r: 13pt;
    --fn-header-c: 'Livorna', 'David Libre', 'David', serif;
    --sz-header-c: 11pt;
    --fn-header-l: 'Livorna', 'David Libre', 'David', serif;
    --sz-header-l: 13pt;
    --hdr-w-r: 33.33%;
    --hdr-w-c: 33.34%;
    --hdr-w-l: 33.33%;

    --fn-h0: 'AlphaBlack', 'David Libre', serif;
    --sz-h0: 26pt;
    --fn-h0-body: 'Frank Ruhl Libre', serif;
    --sz-h0-body: 11.5pt;
    --fn-h1: 'Lia Sgula', 'Bellefair', serif;
    --sz-h1: 50pt;
    --fn-h1-sub: 'David Libre', serif;
    --sz-h1-sub: 28pt;
    --fn-h2: 'AlphaBlack', 'David Libre', serif;
    --sz-h2: 17pt;
    --h2-top-distance: 22%;
    --fn-siman: 'AlphaBlack', 'David Libre', serif;
    --sz-siman: 20pt;

    --fn-h3: 'Alpha', 'Noto Serif Hebrew', serif;
    --sz-h3: 13.5pt;
    --fn-h4: 'Alpha', 'Frank Ruhl Libre', serif;
    --sz-h4: 12.5pt;
    --fn-h5: 'AlphaLight', 'David Libre', serif;
    --sz-h5: 11.5pt;
    --fn-h6: 'Noto Serif Hebrew', serif;
    --sz-h6: 10.5pt;
    --fn-h7: 'Hadassah Friedlaender', 'David Libre', serif;
    --sz-h7: 6pt;

    --fn-sh-title: 'Bellefair', serif;
    --sz-sh-title: 46pt;
    --fn-sh-sub: 'David Libre', serif;
    --sz-sh-sub: 21pt;
    --fn-sh-desc: 'Frank Ruhl Libre', serif;
    --sz-sh-desc: 12pt;
    --fn-sh-sec: 'David Libre', serif;
    --sz-sh-sec: 11.5pt;
    --fn-sh-author: 'David Libre', serif;
    --sz-sh-author: 15pt;
    --fn-sh-year: 'David Libre', serif;
    --sz-sh-year: 12pt;

    --fn-body: 'Guttman Rashi', 'Frank Ruhl Libre', serif;
    --sz-body: 11.2pt;
    --line-height-body: 1.34;
    --fn-first-word: 'FrankReal', 'Frank Ruhl Libre', serif;
