# Let's extract the exact CSS rules needed without any duplication.

clean_css = """@import url('https://fonts.googleapis.com/css2?family=Assistant:wght@400;500;600;700;800&family=Rubik:wght@400;500;600;700&family=Bellefair&family=David+Libre:wght@400;500;700&family=Frank+Ruhl+Libre:wght@400;700;900&family=Noto+Serif+Hebrew:wght@400;700;900&display=swap');

/* ============================================================
   משתני CSS גלובליים
   ============================================================ */
:root {
    --preview-scale: 1;

    /* כותרות עליונות */
    --fn-header-r: 'Livorna', 'David Libre', serif;
    --sz-header-r: 13pt;
    --fn-header-c: 'Livorna', 'David Libre', serif;
    --sz-header-c: 11pt;
    --fn-header-l: 'Livorna', 'David Libre', serif;
    --sz-header-l: 13pt;
    --hdr-w-r: 33.33%;
    --hdr-w-c: 33.34%;
    --hdr-w-l: 33.33%;

    /* כותרות 0-7 */
    --fn-h0: 'AlphaBlack', 'David Libre', serif;
    --sz-h0: 26pt;
    --fn-h0-body: 'Frank Ruhl Libre', serif;
    --sz-h0-body: 11.5pt;
    --fn-h1: 'Lia Sgula', 'Bellefair', serif;
    --sz-h1: 50pt;
    --fn-h1-sub: 'David Libre', serif;
    --sz-h1-sub: 28pt;

    --fn-h2: 'AlphaBlack', 'David Libre', serif;
    --sz-h2: 17pt;
    --h2-top-distance: 22%;
    --fn-siman: 'AlphaBlack', 'David Libre', serif;
    --sz-siman: 20pt;

    --fn-h3: 'Alpha', 'Noto Serif Hebrew', serif;
    --sz-h3: 13.5pt;
    --fn-h4: 'Alpha', 'Frank Ruhl Libre', serif;
    --sz-h4: 12.5pt;
    --fn-h5: 'AlphaLight', 'David Libre', serif;
    --sz-h5: 11.5pt;
    --fn-h6: 'Noto Serif Hebrew', serif;
    --sz-h6: 10.5pt;
    --fn-h7: 'Hadassah Friedlaender', 'David Libre', serif;
    --sz-h7: 6pt;

    /* שערים */
    --fn-sh-title: 'Bellefair', serif;
    --sz-sh-title: 46pt;
    --fn-sh-sub: 'David Libre', serif;
    --sz-sh-sub: 21pt;
    --fn-sh-desc: 'Frank Ruhl Libre', serif;
    --sz-sh-desc: 12pt;
    --fn-sh-sec: 'David Libre', serif;
    --sz-sh-sec: 11.5pt;
    --fn-sh-author: 'David Libre', serif;
    --sz-sh-author: 15pt;
    --fn-sh-year: 'David Libre', serif;
    --sz-sh-year: 12pt;

    /* גוף הטקסט ומילה ראשונה */
    --fn-body: 'Guttman Rashi', 'Frank Ruhl Libre', serif;
    --sz-body: 11.2pt;
    --line-height-body: 1.34;
    --fn-first-word: 'FrankReal', 'Frank Ruhl Libre', serif;
    --sz-first-word: 1.5em;

    /* דיבור המתחיל */
    --fn-dh: 'AlphaBlack', 'David Libre', serif;
    --sz-dh: 1em;

    /* כותרת הערות שוליים */
    --fn-note-title: 'David Libre', serif;
    --sz-note-title: 9pt;

    /* רשת העמוד */
    --w-margin: 7.5%;
    --w-gap: 2%;
    --w-col: 40%;
    --w-gutter: 2%;
    --flow-mt: 20px;
    --flow-mb: 20px;
    --flow-mt-h2: 20px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html, body {
    height: 100%;
    width: 100%;
    overflow: hidden;
    font-family: 'Assistant', 'Rubik', system-ui, sans-serif;
    background-color: #334155;
}

body {
    display: flex;
    flex-direction: row;
    color: #0f172a;
}

/* ============================================================
   מבנה סרגל הצד (Sidebar)
   ============================================================ */
#sidebar {
    height: 100vh;
    display: flex;
    flex-direction: row;
    background: #ffffff;
    box-shadow: -4px 0 20px rgba(0, 0, 0, 0.15);
    z-index: 100;
    flex-shrink: 0;
    position: relative;
}

#text-pane {
    width: 440px;
    min-width: 320px;
    height: 100vh;
    display: flex;
    flex-direction: column;
    background: #f8fafc;
    border-left: 1px solid #e2e8f0;
    flex-shrink: 0;
}

.text-pane-header {
    padding: 12px 14px 10px 14px;
    background: #ffffff;
    border-bottom: 1px solid #e2e8f0;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.header-main-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 11pt;
    font-weight: 800;
    color: #0f172a;
}

.text-actions-bar {
    display: flex;
    gap: 6px;
    align-items: center;
}

.btn-tool {
    border: none;
    border-radius: 6px;
    font-family: 'Assistant', 'Rubik', sans-serif;
    font-size: 8.5pt;
    font-weight: 700;
    padding: 6px 10px;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    white-space: nowrap;
}

.btn-primary {
    background: #0f172a;
    color: #ffffff;
    flex: 1.2;
    box-shadow: 0 2px 4px rgba(15, 23, 42, 0.15);
}
.btn-primary:hover { background: #1e293b; transform: translateY(-1px); }

.btn-import { background: #2563eb; color: #ffffff; flex: 1; }
.btn-import:hover { background: #1d4ed8; transform: translateY(-1px); }

.btn-secondary {
    background: #ffffff;
    color: #334155;
    border: 1px solid #cbd5e1;
    flex: 0.8;
}
.btn-secondary:hover { background: #f1f5f9; border-color: #94a3b8; }

.editor-wrapper {
    flex: 1;
    padding: 10px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

#raw-input {
    flex: 1;
    overflow-y: auto;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    padding: 14px 16px;
    font-family: 'David Libre', 'Frank Ruhl Libre', serif;
    font-size: 11pt;
    line-height: 1.6;
    color: #1e293b;
    direction: rtl;
    white-space: pre-wrap;
    word-wrap: break-word;
    outline: none;
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.03);
}

#raw-input:focus {
    border-color: #3b82f6;
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.03), 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.editor-line {
    min-height: 1.4em;
    padding: 1px 4px;
    border-radius: 3px;
    transition: background-color 0.2s ease;
}
.editor-line:hover { background-color: #f8fafc; }

.page-break-divider {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 12px 0 10px 0;
    position: relative;
    user-select: none;
    cursor: default;
    height: 24px;
}

.page-break-divider::before {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 50%;
