}

.editor-target-highlight {
    animation: highlightPulse 1.6s ease;
    border-radius: 4px;
}

.text-pane-footer {
    padding: 6px 14px;
    background: #ffffff;
    border-top: 1px solid #e2e8f0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 7.5pt;
    color: #64748b;
    font-weight: 600;
}

/* ============================================================
