    background: #1e293b;
    color: #94a3b8;
    transition: all 0.2s ease;
    user-select: none;
    gap: 16px;
}
.collapse-strip:hover { background: #334155; color: #f8fafc; }
#settings-pane.collapsed .collapse-strip { display: flex; }

.collapse-icon { font-size: 11pt; font-weight: bold; }
.collapse-label {
    writing-mode: vertical-rl;
    transform: rotate(180deg);
    font-size: 8.5pt;
    font-weight: 700;
    letter-spacing: 1.5px;
    white-space: nowrap;
}

.settings-content {
    flex: 1;
    height: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #ffffff;
}
#settings-pane.collapsed .settings-content { display: none; }

.settings-top-bar {
    padding: 10px 12px;
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.settings-title { font-size: 10pt; font-weight: 800; color: #0f172a; }

.settings-quick-actions { display: flex; gap: 5px; align-items: center; }

.btn-header-action {
    border: none;
    padding: 4px 8px;
    border-radius: 5px;
    font-size: 8pt;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
