}

.inline-cfg-row {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 6px;
    font-size: 8.5pt;
}

.inline-cfg-row label {
    font-weight: 700;
    width: 105px;
    flex-shrink: 0;
    font-size: 8pt;
    color: #475569;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.inline-cfg-row input[type="text"], .inline-cfg-row select {
    padding: 4px 6px;
    font-size: 8.5pt;
    border: 1px solid #cbd5e1;
    border-radius: 5px;
    font-family: inherit;
    color: #1e293b;
    background-color: #ffffff;
}

.inline-cfg-row select:focus, .inline-cfg-row input[type="text"]:focus {
    border-color: #3b82f6;
    outline: none;
}

.inline-cfg-row select.font-picker { width: 110px; }

.inline-cfg-row input.size-input {
    width: 44px;
    text-align: center;
    font-size: 8.5pt;
    padding: 4px 2px;
    border: 1px solid #cbd5e1;
    border-radius: 5px;
}

.dim-box {
    display: flex;
    align-items: center;
    gap: 4px;
    background: #f8fafc;
    padding: 4px 6px;
    border: 1px solid #e2e8f0;
    border-radius: 5px;
    margin-top: 4px;
    margin-bottom: 6px;
}
.dim-box label { font-size: 7.2pt; font-weight: 700; color: #475569; width: auto !important; }
.dim-box input {
    width: 52px; font-size: 7.5pt; padding: 2px 4px; text-align: center;
    border: 1px solid #cbd5e1; border-radius: 4px;
}

/* טוגלים (Toggles) */
.toggle-buttons-group {
    display: flex;
    gap: 6px;
    margin-bottom: 8px;
    flex-wrap: wrap;
}

.btn-toggle {
    display: inline-flex;
    cursor: pointer;
    user-select: none;
    position: relative;
}
.btn-toggle.full-width { width: 100%; }
.btn-toggle.full-width .btn-toggle-box { width: 100%; }

.btn-toggle input[type="checkbox"] {
    position: absolute; opacity: 0; width: 0; height: 0; pointer-events: none;
}

.btn-toggle-box {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 10px;
    background: #f1f5f9;
    color: #475569;
    border: 1.5px solid #cbd5e1;
    border-radius: 7px;
    font-size: 8.2pt;
    font-weight: 700;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}
.btn-toggle:hover .btn-toggle-box { background: #e2e8f0; border-color: #94a3b8; color: #0f172a; }
.btn-toggle input[type="checkbox"]:checked + .btn-toggle-box {
    background: #2563eb; border-color: #1d4ed8; color: #ffffff; box-shadow: 0 1px 4px rgba(37, 99, 235, 0.3);
}

.btn-toggle .check-icon {
    font-size: 8pt; font-weight: 900; opacity: 0; transform: scale(0.5); transition: all 0.15s ease; width: 8px;
}
.btn-toggle input[type="checkbox"]:checked + .btn-toggle-box .check-icon { opacity: 1; transform: scale(1); }

.btn-toggle-mini {
    display: inline-flex; cursor: pointer; user-select: none; position: relative;
}
.btn-toggle-mini input[type="checkbox"] {
    position: absolute; opacity: 0; width: 0; height: 0; pointer-events: none;
}
.btn-toggle-mini-box {
    display: inline-flex; align-items: center; padding: 2px 6px; background: #f1f5f9; color: #64748b;
    border: 1px solid #cbd5e1; border-radius: 5px; font-size: 7.2pt; font-weight: 700; transition: all 0.15s ease; white-space: nowrap;
}
.btn-toggle-mini:hover .btn-toggle-mini-box { background: #e2e8f0; }
.btn-toggle-mini input[type="checkbox"]:checked + .btn-toggle-mini-box {
    background: #0f172a; border-color: #0f172a; color: #ffffff;
}

.btn-toggle-cell {
    display: inline-flex; cursor: pointer; user-select: none; position: relative; justify-content: center; width: 100%;
}
.btn-toggle-cell input[type="checkbox"] {
    position: absolute; opacity: 0; width: 0; height: 0; pointer-events: none;
}
.btn-toggle-cell .cell-box {
    display: inline-flex; justify-content: center; align-items: center; padding: 2px 8px; border-radius: 4px;
    font-size: 7.5pt; font-weight: 700; background: #f1f5f9; color: #64748b; border: 1px solid #cbd5e1; transition: all 0.15s ease;
}
.btn-toggle-cell:hover .cell-box { background: #e2e8f0; }
.btn-toggle-cell input[type="checkbox"]:checked + .cell-box {
    background: #10b981; border-color: #059669; color: #ffffff;
}

.toc-levels-table {
    width: 100%; font-size: 8pt; margin-top: 4px; border-collapse: collapse;
}
.toc-levels-table th, .toc-levels-table td { padding: 3px 4px; text-align: right; }
.toc-levels-table th { background: #f8fafc; color: #475569; font-weight: 800; border-bottom: 1px solid #e2e8f0; }

#resizer {
    width: 6px; height: 100vh; background: #1e293b; cursor: col-resize; flex-shrink: 0; z-index: 110; transition: background 0.2s;
}
#resizer:hover, #resizer.resizing { background: #3b82f6; }

/* ============================================================
   תצוגה מקדימה (Preview) ודפי A4
   ============================================================ */
#preview-pane {
    flex: 1; height: 100vh; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column;
    align-items: center; padding: 24px 16px; scroll-behavior: smooth; background-color: #334155; position: relative;
}

#book-container {
    display: flex; flex-direction: column; align-items: center; transform-origin: top center;
    transform: scale(var(--preview-scale, 1)); transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1); will-change: transform;
}

.a4-page {
    background-color: #ffffff; width: 210mm; height: 297mm; max-height: 297mm; padding: 15mm;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35); position: relative; margin-bottom: 25px;
    page-break-after: always; overflow: hidden; flex-shrink: 0; cursor: pointer; transition: box-shadow 0.2s ease, outline 0.2s ease;
}
.a4-page:hover { box-shadow: 0 8px 30px rgba(0, 0, 0, 0.45); }
.a4-page.page-focused {
    outline: 4px solid #3b82f6 !important; box-shadow: 0 0 25px rgba(59, 130, 246, 0.5) !important;
}

.page-content-wrapper {
    display: flex; flex-direction: column; height: 100%; width: 100%; position: relative; justify-content: space-between;
}

/* עמודי שער */
.main-shaar-page { display: flex; justify-content: center; align-items: center; position: relative; padding: 0; }
.shaar-main-content {
    width: 100%; height: 80%; display: flex; flex-direction: column; justify-content: space-between;
    align-items: center; text-align: center; padding: 20mm 12mm 16mm 12mm; z-index: 20; position: relative;
}
.custom-bg-img {
    position: absolute; top: 0; bottom: 0; left: 0; right: 0; width: 100% !important; height: 100% !important;
    object-fit: fill !important; z-index: 5; pointer-events: none;
}
.bsd-header { font-family: 'David Libre', serif; font-size: 15pt; letter-spacing: 5px; font-weight: 700; margin-bottom: 40px; }
.sefer-label { font-family: 'David Libre', serif; font-size: 15pt; letter-spacing: 5px; font-weight: 700; margin-top: 4px; }
.book-title-main { font-family: var(--fn-sh-title); font-size: var(--sz-sh-title); line-height: 1.1; margin: 10px 0 40px 0; }
.book-subtitle { font-family: var(--fn-sh-sub); font-size: var(--sz-sh-sub); font-weight: 700; line-height: 1.25; }
.book-description { font-family: var(--fn-sh-desc); font-size: var(--sz-sh-desc); line-height: 1.5; max-width: 65%; margin: 10px auto; }
.book-sections-summary {
    font-family: var(--fn-sh-sec); font-size: var(--sz-sh-sec); line-height: 1.5; border-top: 1px solid #ccc;
    border-bottom: 1px solid #ccc; padding: 6px 12px; margin: 8px 0; font-weight: 700;
}
.author-block { font-family: var(--fn-sh-author); font-size: calc(var(--sz-sh-author) * 0.85); line-height: 1.3; }
.author-name { font-size: var(--sz-sh-author); font-weight: 700; }
.publication-footer { font-family: var(--fn-sh-year); font-size: var(--sz-sh-year); font-weight: 700; letter-spacing: 1px; }

/* רקעי שערים מובנים */
.m1-bg-top {
    position: absolute; top: 0; left: 0; right: 0; height: 20%;
    background: linear-gradient(135deg, #f2f2f2 0%, #e2e2e2 100%); border-bottom: 1px solid #d0d0d0;
}
.m1-bg-middle { position: absolute; top: 20%; left: 0; right: 0; height: 60%; background: #ffffff; }
.m1-bg-bottom {
    position: absolute; bottom: 0; left: 0; right: 0; height: 20%;
    background: linear-gradient(135deg, #f2f2f2 0%, #e2e2e2 100%); border-top: 1px solid #d0d0d0;
}
.m1-panel {
    position: absolute; top: 0; bottom: 0; left: 12%; right: 12%; background: #ffffff;
    border-right: 1px solid #ccc; border-left: 1px solid #ccc; box-shadow: 0 0 20px rgba(0,0,0,0.1);
    display: flex; justify-content: space-between; z-index: 10;
}
.m1-damask {
    width: 30px; height: 100%;
    background: #fafafa url("data:image/svg+xml,%3Csvg width='32' height='55' viewBox='0 0 32 55' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M16,27 C10,22 5,14 5,5 C5,0 10,0 16,5 C22,0 27,0 27,5 C27,14 22,22 16,27 Z M16,27 C10,32 5,40 5,49 C5,55 10,55 16,49 C22,55 27,55 27,49 C27,40 22,32 16,27 Z M16,14 A3.5,3.5 0 1,0 16,21 A3.5,3.5 0 1,0 16,14 Z' fill='%239e9e9e' fill-opacity='0.35'/%3E%3C/svg%3E") repeat-y;
    flex-shrink: 0;
}

.m2-bg-top { position: absolute; top: 0; left: 0; right: 0; height: 18%; background: #eaeaea; }
.m2-bg-middle {
    position: absolute; top: 18%; left: 0; right: 0; height: 64%; background: #ffffff;
    box-shadow: inset 0 2px 6px rgba(0,0,0,0.06), inset 0 -2px 6px rgba(0,0,0,0.06);
}
.m2-bg-bottom { position: absolute; bottom: 0; left: 0; right: 0; height: 18%; background: #eaeaea; }
.m2-panel {
    position: absolute; top: 0; bottom: 0; left: 10%; right: 10%; background: #ffffff;
    box-shadow: 0 0 25px rgba(0,0,0,0.12); display: flex; justify-content: space-between; z-index: 10;
}
.m2-lace {
    width: 24px; height: 100%;
    background: #ffffff url("data:image/svg+xml,%3Csvg width='26' height='40' viewBox='0 0 26 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M13,20 C4,16 2,8 2,2 C2,0 8,0 13,8 C18,0 24,0 24,2 C24,8 22,16 13,20 Z M13,20 C4,24 2,32 2,38 C2,40 8,40 13,32 C18,40 24,40 24,38 C24,32 22,24 13,20 Z M13,10 A3,3 0 1,0 13,16 A3,3 0 1,0 13,10 Z M13,30 A3,3 0 1,0 13,24 A3,3 0 1,0 13,30 Z' fill='%23888888' fill-opacity='0.45'/%3E%3C/svg%3E") repeat-y;
    flex-shrink: 0;
}

.m3-wavy-band {
    position: absolute; top: 14%; left: 0; right: 0; height: 72%; background: #ffffff;
    border-top: 1.5px solid #d4d4d4; border-bottom: 1.5px solid #d4d4d4;
}
.m3-panel {
    position: absolute; top: 0; bottom: 0; left: 9%; right: 9%; background: #ffffff;
    border-right: 1.5px solid #ccc; border-left: 1.5px solid #ccc; box-shadow: 0 0 25px rgba(0,0,0,0.14); z-index: 10;
}
.m3-corner { position: absolute; width: 65px; height: 65px; fill: #111; z-index: 25; }
.m3-corner.tr { top: 10mm; right: 10mm; }
.m3-corner.tl { top: 10mm; left: 10mm; transform: scaleX(-1); }
.m3-corner.br { bottom: 10mm; right: 10mm; transform: scaleY(-1); }
.m3-corner.bl { bottom: 10mm; left: 10mm; transform: scale(-1, -1); }

.sub-shaar-page, .back-shaar-page { position: relative; padding: 0; }
.sub-shaar-bg-right { position: absolute; top: 0; bottom: 0; right: 0; left: 55%; background: #f4f4f4; }
.back-shaar-bg-left { position: absolute; top: 0; bottom: 0; left: 0; right: 55%; background: #f4f4f4; }

.theme-bounded-content {
    position: absolute; width: auto !important; height: auto !important; display: flex; flex-direction: column;
    justify-content: space-between; align-items: center; text-align: center; z-index: 20; box-sizing: border-box;
    border: 1.5px dashed rgba(37, 99, 235, 0.4); transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.theme-bounded-content:hover { border-color: #2563eb; box-shadow: 0 0 10px rgba(37, 99, 235, 0.15); }

/* תוכן העניינים */
.toc-page { padding: 15mm; }
.toc-grid-full {
    display: flex; flex-direction: column; gap: 3px; justify-content: space-between;
    flex-grow: 1; width: 100%; max-width: 175mm; margin: 0 auto;
}
.toc-entry-group { break-inside: avoid; margin-bottom: 3px; }
.toc-item {
    display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 2px;
    font-family: 'David Libre', serif; font-size: 10.5pt;
}
.toc-title { flex-shrink: 1; max-width: 84%; font-weight: 600; white-space: normal; word-wrap: break-word; line-height: 1.3; }
.toc-dots { flex-grow: 1; border-bottom: 1px dotted #777; margin: 0 8px; height: 1px; min-width: 25px; }
.toc-page-num { flex-shrink: 0; font-weight: 700; font-family: 'David Libre', serif; font-size: 10.5pt; min-width: 25px; text-align: left; }

.toc-lvl-1 { font-size: 12pt; font-weight: 700; margin-top: 8px; margin-bottom: 3px; border-bottom: 1px solid #ddd; padding-bottom: 2px; }
.toc-lvl-2 { font-size: 11pt; font-weight: 700; margin-top: 5px; padding-right: 8px; }
.toc-lvl-3 { font-size: 10.5pt; font-weight: 700; padding-right: 16px; }
.toc-lvl-4 { padding-right: 24px; font-size: 10pt; }
.toc-lvl-5 { padding-right: 32px; font-size: 9.5pt; }
.toc-lvl-6 { padding-right: 40px; font-size: 9pt; }
.toc-lvl-7 { padding-right: 48px; font-size: 8.8pt; }

.toc-grouped-block { padding-right: 30px; font-size: 9pt; color: #222; line-height: 1.5; margin: 2px 0 5px 0; text-align: right; }
.grp-item { font-size: inherit; white-space: normal; }
.grp-title { font-weight: 600; color: #111; }
.grp-page { font-weight: 700; color: #4a5568 !important; }
.grp-sep { color: #888; margin: 0 6px; font-weight: bold; }

/* ============================================================
   כותרת עליונה (Running Header)
   ============================================================ */
.top-header-grid {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    height: 26px;
    flex-shrink: 0;
    width: 100%;
    border-bottom: 1px solid rgba(0,0,0,0.06);
    padding-bottom: 3px;
    margin-bottom: 4px;
}

.header-col-r {
    width: var(--hdr-w-r, 33.33%);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: var(--fn-header-r);
    font-size: var(--sz-header-r);
    font-weight: 700;
}

.header-col-c {
    width: var(--hdr-w-c, 33.34%);
    display: flex;
    align-items: center;
    overflow: visible;
    font-family: var(--fn-header-c);
    font-size: var(--sz-header-c);
}

.header-col-l {
    width: var(--hdr-w-l, 33.33%);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: var(--fn-header-l);
    font-size: var(--sz-header-l);
    font-weight: 700;
}

/* ============================================================
   כותרת 2, זרימת דף וטורים
   ============================================================ */
.title-level-2-standalone {
    font-family: var(--fn-h2);
    font-size: var(--sz-h2);
    font-weight: 700;
    text-align: center;
    margin-top: 0;
    margin-bottom: 20px;
    width: 100%;
    line-height: 1.25;
    flex-shrink: 0;
}

.h2-spacer {
    flex-basis: var(--h2-top-distance, 22%);
    flex-shrink: 0;
}

.page-body-flow {
    display: flex;
    flex-direction: column;
    width: 100%;
    position: relative;
    flex-grow: 1;
    justify-content: flex-start;
    margin-top: var(--flow-mt);
    margin-bottom: var(--flow-mb);
    min-height: 0;
}

.page-body-flow.h2-flow-page {
    margin-top: var(--flow-mt-h2, var(--flow-mt));
}

.block-2col {
    display: grid;
    grid-template-columns: var(--w-margin) var(--w-gap) var(--w-col) var(--w-gutter) var(--w-col) var(--w-gap) var(--w-margin);
    width: 100%;
    position: relative;
    align-items: start;
}

/* קו מפריד אנכי בין הטורים */
.col-gutter-divider {
    grid-column: 4;
    height: 100%;
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: stretch;
    pointer-events: none;
}

.col-rule-none { display: none; }
.col-rule-plain {
    width: 1px;
    background-color: #777;
    margin: 4px auto;
}
.col-rule-dashed {
    width: 0px;
    border-left: 1px dashed #777;
    margin: 4px auto;
}
.col-rule-double {
    width: 3px;
    border-left: 1px solid #777;
    border-right: 1px solid #777;
    margin: 4px auto;
}

/* ============================================================
   כותרות 3 עד 7, כותרות מובלעות (Run-in)
   ============================================================ */
.block-h3-span {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 10px !important;
    margin-right: calc(var(--w-margin) + var(--w-gap)) !important;
    margin-left: calc(var(--w-margin) + var(--w-gap)) !important;
    width: calc(100% - 2 * (var(--w-margin) + var(--w-gap))) !important;
    padding: 8px 0 4px 0;
    margin-bottom: 4px;
    flex-shrink: 0;
    box-sizing: border-box;
}

.block-h3-span .h3-title-text {
    font-family: var(--fn-h3);
    font-size: var(--sz-h3);
    font-weight: 900;
    text-align: center;
    width: auto !important;
    max-width: 80%;
    line-height: 1.22;
    flex-shrink: 1;
}

.h3-ornament-right, .h3-ornament-left {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
}

.title-level-4 {
    font-family: var(--fn-h4);
    font-size: var(--sz-h4);
    font-weight: 900;
    text-align: center;
    margin: 9px 0 4px 0;
    line-height: 1.22;
}

.title-level-5 {
    font-family: var(--fn-h5);
    font-size: var(--sz-h5);
    font-weight: 700;
    text-align: center;
    margin: 7px 0 3px 0;
    line-height: 1.22;
}

.title-level-6 {
    font-family: var(--fn-h6);
    font-size: var(--sz-h6);
    font-weight: 700;
    text-align: center;
    margin: 6px 0 3px 0;
    line-height: 1.22;
}

.title-level-custom {
    margin: 9px 0 4px 0;
    line-height: 1.3;
}

.heading-run-in {
    font-weight: 900;
    display: inline;
    margin-left: 6px;
}

.block-single-col {
    display: grid;
    grid-template-columns: var(--w-margin) var(--w-gap) calc(var(--w-col)*2 + var(--w-gutter)) var(--w-gap) var(--w-margin);
    width: 100%;
    position: relative;
    align-items: start;
}

.block-single-col .single-wide-col {
    grid-column: 3;
    font-family: var(--fn-h0-body);
    font-size: var(--sz-h0-body);
    line-height: 1.45;
    text-align: justify;
    text-justify: inter-word;
}

.margin-notes-column {
    font-family: var(--fn-h7);
    font-size: var(--sz-h7);
    line-height: 1.18;
    text-align: center;
    text-align-last: center;
    font-weight: 400;
    color: #404040;
    position: relative;
    width: 100%;
    height: 100%;
}

.right-margin { grid-column: 1; }
.left-margin { grid-column: 7; }

.side-note-anchor {
    position: absolute;
    width: 100%;
}

.main-column {
    font-family: var(--fn-body);
    font-size: var(--sz-body);
    line-height: var(--line-height-body, 1.34);
    text-align: justify;
    text-justify: inter-word;
    min-height: 0;
    height: auto;
    position: relative;
}

.right-col { grid-column: 3; }
.left-col { grid-column: 5; }

p {
    margin-bottom: 7px;
    text-align: justify;
    text-justify: inter-word;
    position: relative;
    line-height: var(--line-height-body, 1.34);
}

p.p-end { text-align-last: center; }
p.p-cut { text-align-last: justify; }

/* מילה ראשונה (חלון / מוגדל / מודגש) */
.first-word-window {
    float: right;
    font-family: var(--fn-first-word);
    font-size: var(--sz-first-word);
    font-weight: 900;
    line-height: 0.85;
    height: 1.25em;
    margin-left: 6px;
    margin-bottom: 1px;
    display: block;
}

.first-word-inline {
    font-family: var(--fn-first-word);
    font-size: var(--sz-first-word);
    font-weight: 900;
    line-height: 1;
    margin-left: 4px;
}

.first-word-bold {
    font-family: var(--fn-first-word);
    font-weight: 900;
    margin-left: 4px;
}

/* דיבור המתחיל (ד"ה) */
.dibbur-hamatchil {
    font-family: var(--fn-dh, var(--fn-body));
    font-weight: 900;
    display: inline;
}

/* ============================================================
   הערות שוליים וסיום
   ============================================================ */
.footnote-area {
    position: relative;
