    height: 20px;
    padding: 1px 4px;
}

.page-num-frame-paren::before {
    content: '(';
    margin-left: 2px;
}

.page-num-frame-paren::after {
    content: ')';
    margin-right: 2px;
}

.page-num-frame-brackets::before {
    content: '[';
    margin-left: 2px;
}

.page-num-frame-brackets::after {
    content: ']';
    margin-right: 2px;
}

.page-num-frame-diamonds::before {
    content: '◈ ';
    font-size: 8pt;
    margin-left: 3px;
}

.page-num-frame-diamonds::after {
    content: ' ◈';
    font-size: 8pt;
    margin-right: 3px;
}

#measuring-box {
