function toGematria(num) {
    num = parseInt(num, 10);
    if (isNaN(num) || num <= 0)
        return "";
    if (num === 15)
        return "טו";
    if (num === 16)
        return "טז";
    const hundreds = ["", "ק", "ר", "ש", "ת", "תק", "תר", "תש", "תת", "תתק"];
    const tens = ["", "י", "כ", "ל", "מ", "נ", "ס", "ע", "פ", "צ"];
    const ones = ["", "א", "ב", "ג", "ד", "ה", "ו", "ז", "ח", "ט"];
    let str = "";
    let h = Math.floor(num / 100);
    if (h > 0) {
        if (h <= 4)
            str += ["", "ק", "ר", "ש", "ת"][h];
        else if (h < hundreds.length)
            str += hundreds[h];
        num %= 100;
    }
    let t = Math.floor(num / 10);
    let o = num % 10;
    if (t === 1 && (o === 5 || o === 6)) {
        str += (o === 5) ? "טו" : "טז";
    } else {
        str += tens[t] + ones[o];
    }
    return str;
}

