function saveAsDefaultTemplate() {
    let dataIsland = document.getElementById('ext-imports-data');
    if (!dataIsland) {
        dataIsland = document.createElement('script');
        dataIsland.type = 'application/json';
        dataIsland.id = 'ext-imports-data';
