html, body {
    height: 100%;
    width: 100%;
    overflow: hidden;
    font-family: 'Assistant', 'Rubik', system-ui, sans-serif;
    background-color: #334155;
}

body {
    display: flex;
    flex-direction: row;
    color: #0f172a;
}

/* סרגל הצד (Sidebar) ואזור עורך הטקסט */
#sidebar {
    height: 100vh;
    display: flex;
    flex-direction: row;
    background: #ffffff;
    box-shadow: -4px 0 20px rgba(0, 0, 0, 0.15);
    z-index: 100;
    flex-shrink: 0;
    position: relative;
}

#text-pane {
    width: 440px;
    min-width: 320px;
    height: 100vh;
    display: flex;
    flex-direction: column;
    background: #f8fafc;
    border-left: 1px solid #e2e8f0;
    flex-shrink: 0;
}

.text-pane-header {
    padding: 12px 14px 10px 14px;
    background: #ffffff;
    border-bottom: 1px solid #e2e8f0;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.header-main-title {
    display: flex;
    align-items: center;
    gap: 8px;
