.editor-wrapper {
    flex: 1;
    padding: 10px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

#raw-input {
    flex: 1;
    overflow-y: auto;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    padding: 14px 16px;
    font-family: 'David Libre', 'Frank Ruhl Libre', serif;
    font-size: 11pt;
    line-height: 1.6;
    color: #1e293b;
    direction: rtl;
    white-space: pre-wrap;
    word-wrap: break-word;
    outline: none;
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.03);
}

#raw-input:focus {
    border-color: #3b82f6;
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.03), 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.editor-line {
    min-height: 1.4em;
    padding: 1px 4px;
    border-radius: 3px;
    transition: background-color 0.2s ease;
}
.editor-line:hover { background-color: #f8fafc; }

.page-break-divider {
    display: flex;
    align-items: center;
    justify-content: center;
