/* לוח ההגדרות (Settings Pane) ורכיבי טופס */
#settings-pane {
    width: 440px;
    height: 100vh;
    display: flex;
    flex-direction: row;
    background: #ffffff;
    border-left: 1px solid #e2e8f0;
    transition: width 0.25s cubic-bezier(0.4, 0, 0.2, 1);
