    color: #94a3b8;
    transition: all 0.2s ease;
    user-select: none;
    gap: 16px;
}
.collapse-strip:hover { background: #334155; color: #f8fafc; }
#settings-pane.collapsed .collapse-strip { display: flex; }

.collapse-icon { font-size: 11pt; font-weight: bold; }
.collapse-label {
    writing-mode: vertical-rl;
